CsvImportTemplateDefinition byType(ImportTemplateType type)=>csvImportTemplates.firstWhere((x)=>x.type==type);
CsvImportTemplateDefinition? byId(String id){for(final x in csvImportTemplates){if(x.id==id)return x;}return null;}
